// The NasBuster ghost: transparent pixel art with its own black outline, for both themes
// (generated by tools/logo from the logo pack).
// Decorative: the product name is always written next to it.
import { cn } from '../lib/cn'
import logo128 from '../assets/nasbuster-128.png'
import logo256 from '../assets/nasbuster-256.png'
import logo64 from '../assets/nasbuster-64.png'

/** Smallest source that stays sharp at 2x for the displayed size. */
function sources(size: number): { src: string; srcSet: string } {
  if (size <= 32) return { src: logo64, srcSet: `${logo64} 2x` }
  if (size <= 64) return { src: logo64, srcSet: `${logo128} 2x` }
  return { src: logo128, srcSet: `${logo256} 2x` }
}

export function Logo({ size, className }: { size: number; className?: string }) {
  return (
    <img
      {...sources(size)}
      alt=""
      aria-hidden="true"
      width={size}
      height={size}
      draggable={false}
      className={cn('shrink-0 select-none', className)}
    />
  )
}
